use std::sync::Arc;
use maho_omo_task::planner::create_task_child_planner;
use senpi_task::{agents::map_omo_config_agents,host::{SenpiModelRegistry,HostError},manager::types::{ManagerStartSpec,ResolvedChildPlan}};
use serde_json::{Value,json};
struct Registry(Value);
impl SenpiModelRegistry for Registry { fn get_available(&self)->Result<Value,HostError> { Ok(json!([self.0])) } fn find(&self,provider:&str,id:&str)->Option<Value> { (self.0["provider"]==provider && self.0["id"]==id).then(|| self.0.clone()) } }
fn plan(agent:Value)->ResolvedChildPlan {
    let config=json!({"agents":{"explore":agent}}); let agents=map_omo_config_agents(&config).into_iter().collect();
    let registry=Arc::new(Registry(json!({"provider":"openai","id":"tuned"})));
    let planner=create_task_child_planner(config,agents,Arc::new(move || Some(registry.clone())));
    planner(&ManagerStartSpec { subagent_type:Some("explore".into()),prompt:"work".into(),parent_session_id:"parent".into(),depth:1,..Default::default() }).expect("resolved")
}
#[test] fn model_entry_effort_becomes_child_variant() { let result=plan(json!({"models":[{"model":"openai/tuned","reasoningEffort":"minimal"}]})); assert_eq!(result.variant.as_deref(),Some("minimal")); assert_eq!(result.resolved_model.expect("model").reasoning_effort.as_deref(),Some("minimal")); }
#[test] fn entry_effort_wins_over_entry_variant() { assert_eq!(plan(json!({"models":[{"model":"openai/tuned","variant":"high","reasoningEffort":"minimal"}]})).variant.as_deref(),Some("minimal")); }
#[test] fn entry_effort_wins_over_agent_variant() { assert_eq!(plan(json!({"variant":"high","models":[{"model":"openai/tuned","reasoningEffort":"minimal"}]})).variant.as_deref(),Some("minimal")); }
#[test] fn plain_model_does_not_invent_variant() { assert!(plan(json!({"models":["openai/tuned"]})).variant.is_none()); }
#[test] fn category_preserves_safe_registry_display_name() { let registry=Arc::new(Registry(json!({"provider":"openai","id":"tuned","name":"Friendly Model"}))); let planner=create_task_child_planner(json!({"categories":{"quick":{"model":"openai/tuned"}}}),vec![],Arc::new(move || Some(registry.clone()))); assert_eq!(planner(&ManagerStartSpec { category:Some("quick".into()),..Default::default() }).expect("resolved").resolved_model.expect("model").display,"Friendly Model"); }
#[test] fn category_rejects_registry_display_control_sequences() { let registry=Arc::new(Registry(json!({"provider":"openai","id":"tuned","name":"unsafe\u{1b}[31m"}))); let planner=create_task_child_planner(json!({"categories":{"quick":{"model":"openai/tuned"}}}),vec![],Arc::new(move || Some(registry.clone()))); assert_eq!(planner(&ManagerStartSpec { category:Some("quick".into()),..Default::default() }).expect("resolved").resolved_model.expect("model").display,"openai/tuned"); }
#[test] fn category_effort_wins_public_variant_but_keeps_both_metadata_fields() { let registry=Arc::new(Registry(json!({"provider":"openai","id":"tuned"}))); let planner=create_task_child_planner(json!({"categories":{"quick":{"model":"openai/tuned","variant":"high","reasoningEffort":"xhigh"}}}),vec![],Arc::new(move || Some(registry.clone()))); let result=planner(&ManagerStartSpec { category:Some("quick".into()),..Default::default() }).expect("plan"); assert_eq!(result.variant.as_deref(),Some("xhigh")); let metadata=result.resolved_model.expect("metadata"); assert_eq!(metadata.variant.as_deref(),Some("high")); assert_eq!(metadata.reasoning_effort.as_deref(),Some("xhigh")); }
#[test] fn explicit_builtin_agent_keeps_persona_without_registry() { let agents=maho_omo_task::engine_runners::resolve_task_agents(&json!({})).into_iter().collect(); let planner=create_task_child_planner(json!({}),agents,Arc::new(|| None)); let result=planner(&ManagerStartSpec { subagent_type:Some("momus".into()),model:Some("openai/tuned".into()),..Default::default() }).expect("explicit plan"); assert_eq!(result.agent_type.as_deref(),Some("momus")); assert!(result.instructions.is_some()); assert_eq!(result.tool_allowlist.expect("tools").len(),9); assert_eq!(result.agent_execution_mode,Some(senpi_task::manager::execution_mode::ExecutionMode::InProcess)); assert!(result.variant.is_none()); }
#[test] fn builtin_agent_fails_closed_without_registry() { let agents=maho_omo_task::engine_runners::resolve_task_agents(&json!({})).into_iter().collect(); let planner=create_task_child_planner(json!({}),agents,Arc::new(|| None)); assert_eq!(planner(&ManagerStartSpec { subagent_type:Some("explore".into()),..Default::default() }).expect_err("no registry").code,senpi_task::manager::types::PlanResolutionCode::ModelUnavailable); }
#[test] fn variant_bearing_builtin_category_fallback_applies_variant() { let registry=Arc::new(Registry(json!({"provider":"zai-coding-plan","id":"glm-5.2"}))); let planner=create_task_child_planner(json!({}),vec![],Arc::new(move || Some(registry.clone()))); let result=planner(&ManagerStartSpec { category:Some("visual-engineering".into()),..Default::default() }).expect("fallback"); assert_eq!(result.variant.as_deref(),Some("max")); assert_eq!(result.resolved_model.expect("metadata").variant.as_deref(),Some("max")); }
#[test] fn curated_agent_fallback_applies_its_reasoning_variant() { let registry=Arc::new(Registry(json!({"provider":"openai","id":"gpt-5.6-sol"}))); let agents=maho_omo_task::engine_runners::resolve_task_agents(&json!({})).into_iter().collect(); let planner=create_task_child_planner(json!({}),agents,Arc::new(move || Some(registry.clone()))); let result=planner(&ManagerStartSpec { subagent_type:Some("momus".into()),..Default::default() }).expect("fallback"); assert_eq!(result.model,"openai/gpt-5.6-sol"); assert_eq!(result.variant.as_deref(),Some("xhigh")); }
#[test] fn disabled_agent_can_fall_back_to_same_named_category_without_explicit_override() { let config=json!({"agents":{"explore":{"disable":true}},"categories":{"explore":{"model":"openai/tuned"}}}); let agents=maho_omo_task::engine_runners::resolve_task_agents(&config).into_iter().collect(); let registry=Arc::new(Registry(json!({"provider":"openai","id":"tuned"}))); let planner=create_task_child_planner(config,agents,Arc::new(move || Some(registry.clone()))); let result=planner(&ManagerStartSpec { subagent_type:Some("explore".into()),..Default::default() }).expect("category alias"); assert_eq!(result.category.as_deref(),Some("explore")); assert!(result.agent_type.is_none()); }
